{
  "angles": [
    {
      "angle": "Bitcoin is the escape from a world where you had no choice but to use government money, and it is building a new internet for 8 billion people.",
      "moments": ["863cc95ab7c5e0c11482", "5d5e163125435e85061a", "8055c5252b61b9639cbe", "030becff03b4f1f0555e"],
      "hook": "863cc95ab7c5e0c11482",
      "support": {
        "863cc95ab7c5e0c11482": "Hook: 'we have no choice… You had to sign up to the government's money' names the problem in one breath and sets up the freedom angle.",
        "5d5e163125435e85061a": "Adds the legal dimension: even today Congress controls the purse strings. 'And certainly' extends the government-control point from history to present law.",
        "8055c5252b61b9639cbe": "Pivots with 'But' from the constraint to the vision: a new internet bound by Bitcoin providing abundance to 8 billion people.",
        "030becff03b4f1f0555e": "'So' lands the practical takeaway: capturing this vision demands a long time horizon for capital managers."
      }
    },
    {
      "angle": "Bitcoin creates its own monetary system through real credit and a new internet, and capturing that requires a long-term horizon.",
      "moments": ["40ffa6e345a223d30429", "8055c5252b61b9639cbe", "030becff03b4f1f0555e"],
      "hook": "40ffa6e345a223d30429",
      "support": {
        "40ffa6e345a223d30429": "Hook: 'You can have Bitcoin, and money will be created' is a bold declarative opener. Walks through credit creation under the Bitcoin standard, ending on 'denominated in something else.'",
        "8055c5252b61b9639cbe": "'But' broadens scope from monetary mechanics to the full-stack vision: a new internet bound by Bitcoin for 8 billion people.",
        "030becff03b4f1f0555e": "'So' converts the grand vision into an investment principle: you must have a long time horizon and ensure managers do too."
      }
    },
    {
      "angle": "Bitcoin is building a new monetary and internet system, but legal access still runs through Congress.",
      "moments": ["40ffa6e345a223d30429", "5d5e163125435e85061a", "8055c5252b61b9639cbe"],
      "hook": "40ffa6e345a223d30429",
      "support": {
        "40ffa6e345a223d30429": "Hook: 'You can have Bitcoin, and money will be created' establishes that Bitcoin generates its own monetary layer. Ends on 'denominated in something else.'",
        "5d5e163125435e85061a": "'And certainly' adds the legal reality check: confidence in Bitcoin purchases still requires Congress authorization; Congress controls the purse strings.",
        "8055c5252b61b9639cbe": "'But' pivots past the constraint to the destination: a new internet bound by Bitcoin providing abundance to 8 billion people."
      }
    }
  ]
}
